import { type ZodType, z } from "zod";

export type GeneratedSchemas = Readonly<Record<string, string>>;

export interface DriftReport {
  /** Committed file exists but differs from the generated output. */
  readonly changed: readonly string[];
  /** Generated but not committed. */
  readonly missing: readonly string[];
  /** Committed but no longer generated by any registered schema. */
  readonly extra: readonly string[];
}

/** Renders each registered Zod schema to a stable, pretty-printed JSON Schema file body. */
export function generateJsonSchemas(registry: Readonly<Record<string, ZodType>>): GeneratedSchemas {
  const out: Record<string, string> = {};
  for (const name of Object.keys(registry).sort()) {
    const schema = registry[name];
    if (schema === undefined) continue;
    out[`${name}.json`] = `${JSON.stringify(z.toJSONSchema(schema), null, 2)}\n`;
  }
  return out;
}

/** Compares generated file bodies against the committed ones, keyed by file name. */
export function compareSchemas(generated: GeneratedSchemas, committed: GeneratedSchemas): DriftReport {
  const changed: string[] = [];
  const missing: string[] = [];
  for (const [file, body] of Object.entries(generated)) {
    const current = committed[file];
    if (current === undefined) missing.push(file);
    else if (current !== body) changed.push(file);
  }
  const extra = Object.keys(committed).filter((file) => !(file in generated));
  return { changed: changed.sort(), missing: missing.sort(), extra: extra.sort() };
}

export function hasDrift(report: DriftReport): boolean {
  return report.changed.length + report.missing.length + report.extra.length > 0;
}
